// INPUT_PULLUP: to jest wejście, a płytka sama pilnuje,
// żeby przy zwolnionym przycisku był tam stan wysoki.
// Dlatego przycisk WCIŚNIĘTY daje stan niski (LOW).
pinMode(____________, INPUT_PULLUP);

// digitalRead sprawdza, co jest na wejściu.
// Podwójny znak == znaczy "sprawdź, czy równa się".
// Pojedynczy = znaczyłby "wpisz wartość" - to inne polecenie.
if (digitalRead(pinPrzyciskL) == LOW) {
  digitalWrite(pinDiodaL, swieci);   // przycisk wciśnięty: migaj
} else {
  digitalWrite(pinDiodaL, LOW);      // zwolniony: dioda zgaszona
}

// prawy kierunkowskaz
const int pinDiodaP    = ____;   // wpisz numer wyprowadzenia diody
const int pinPrzyciskP = ____;   // wpisz numer wyprowadzenia przycisku

// dopisz pod warunkiem dla strony lewej
if (digitalRead(pinPrzyciskP) == LOW) {
  digitalWrite(____________, swieci);
} else {
  digitalWrite(pinDiodaP, LOW);
}

// Moduł przekaźnika ma transoptor, więc sterujemy nim wprost
// z wyprowadzenia płytki — bez tranzystora.
const int pinPrzekaznik = ____;

// Znak || znaczy "lub": wystarczy, że miga którakolwiek strona.
// Znak && znaczy "oraz": oba warunki muszą być spełnione naraz.
bool ktoraskolwiek = (digitalRead(pinPrzyciskL) == LOW)
                  || (digitalRead(pinPrzyciskP) == LOW);
digitalWrite(pinPrzekaznik, ktoraskolwiek && swieci);

// Najpierw ustalamy, które strony mają migać,
// a dopiero na końcu zapalamy diody. Dzięki temu
// światła awaryjne mogą "dołożyć" obie strony naraz.
bool migaLewa  = (digitalRead(pinPrzyciskL) == LOW);
bool migaPrawa = (digitalRead(pinPrzyciskP) == LOW);

if (digitalRead(____________) == LOW) {   // awaryjne wciśnięte
  migaLewa  = true;
  migaPrawa = true;
}

digitalWrite(pinDiodaL, migaLewa  && swieci);
digitalWrite(pinDiodaP, migaPrawa && swieci);
digitalWrite(pinPrzekaznik, (migaLewa || migaPrawa) && swieci);

// TABLICA to kilka wartości pod jedną nazwą.
// pinyLewe[0] to pierwsza dioda, pinyLewe[1] druga i tak dalej.
// KOLEJNOŚĆ W NAWIASACH KLAMROWYCH WYZNACZA KIERUNEK FALI.
int pinyLewe[4] = {____, ____, ____, ____};

int opoznienieFali = ____;   // odstęp między diodami w milisekundach
unsigned long startFali = 0;
int aktualnaDioda = 0;

// PĘTLA FOR: powtórz to samo dla i = 0, 1, 2, 3.
// Zapis i++ znaczy "zwiększ i o jeden".
for (int i = 0; i < 4; i++) {
  pinMode(pinyLewe[i], OUTPUT);
}
pinMode(pinPrzyciskL, INPUT_PULLUP);

// Funkcja zapala kolejne diody jedna po drugiej.
// Wywołujemy ją z MIEJSCA C, gdy manetka jest wciśnięta.
void falaLewa() {
  if (millis() - startFali >= opoznienieFali) {
    startFali = millis();
    if (aktualnaDioda < 4) {
      digitalWrite(pinyLewe[aktualnaDioda], HIGH);
      aktualnaDioda++;
    } else {
      for (int i = 0; i < 4; i++) digitalWrite(pinyLewe[i], LOW);
      aktualnaDioda = 0;
    }
  }
}

if (digitalRead(pinPrzyciskL) == LOW) {
  ____________();          // wywołanie własnej funkcji
} else {
  for (int i = 0; i < 4; i++) digitalWrite(pinyLewe[i], LOW);
  aktualnaDioda = 0;
}

const int pinDANE     = ____;   // wyprowadzenie 14 układu
const int pinZATRZASK = ____;   // wyprowadzenie 12 układu
const int pinZEGAR    = ____;   // wyprowadzenie 11 układu

// Każda liczba to jedna KLATKA animacji.
// Zapis 0b00000001 czyta się od prawej: świeci tylko pierwsza dioda.
// 0b00000011 - dwie pierwsze. 0b11111111 - wszystkie osiem.
byte klatki[] = {
  0b00000001,
  0b00000011,
  0b00000111,
  0b00001111,
  0b00011111,
  0b00111111,
  0b01111111,
  0b11111111
};
int klatka = 0;
unsigned long startKlatki = 0;

// Usuń z tego miejsca WSZYSTKO z poprzednich etapów.
// Zostaje tylko przycisk i obsługa rejestru.
pinMode(pinPrzyciskL, INPUT_PULLUP);

pinMode(pinDANE, OUTPUT);
pinMode(pinZATRZASK, OUTPUT);
pinMode(pinZEGAR, OUTPUT);
pokaz(0);   // na starcie wszystkie diody zgaszone

// Wysyła jedną klatkę do rejestru.
// shiftOut wysyła osiem bitów jeden po drugim,
// a zatrzask sprawia, że diody zmieniają się wszystkie naraz.
void pokaz(byte wzorzec) {
  digitalWrite(pinZATRZASK, LOW);
  shiftOut(pinDANE, pinZEGAR, MSBFIRST, wzorzec);
  digitalWrite(pinZATRZASK, HIGH);
}

if (digitalRead(pinPrzyciskL) == LOW) {
  if (millis() - startKlatki >= 120) {
    startKlatki = millis();
    pokaz(klatki[klatka]);
    klatka++;
    if (klatka >= 8) klatka = 0;
  }
} else {
  pokaz(0);
  klatka = 0;
}

