// WYPEŁNIENIE to udział czasu, przez który napięcie jest włączone.
// Przy małym wypełnieniu do brzęczyka trafia mało energii - gra ciszej.
// Skala: 0 (cisza) do 255. Najgłośniej jest w okolicach 128.
int poziomy[3] = {____, ____, ____};
int wybrany = 0;

// Gra jeden sygnał na aktualnym poziomie głośności,
// po czym przechodzi do następnego poziomu.
void kolejnyPoziom() {
  dzwiekGraj(pinBrzeczyka, 2000);
  dzwiekGlosnosc(pinBrzeczyka, poziomy[wybrany]);
  delay(600);
  dzwiekGlosnosc(pinBrzeczyka, 0);

  wybrany = wybrany + 1;
  if (wybrany > 2) wybrany = 0;   // po trzecim wracamy do pierwszego

  delay(200);   // krótka zwłoka na drgania styków przycisku
}

// PĘTLA FOR: f rośnie od fOd do fDo, za każdym razem o krok.
for (int f = fOd; f <= fDo; f = f + krok) {
  dzwiekGraj(pinBrzeczyka, f);
  delay(5);
}
// i z powrotem w dół
for (int f = fDo; f >= fOd; f = f - ____) {
  dzwiekGraj(pinBrzeczyka, f);
  delay(5);
}

// Ta linia jest w programie bazowym od początku.
// Tylko sprawdzasz, czy nadal tam jest.
dzwiekCisza(pinBrzeczyka);
